-- Node: dka-fluid-management (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Fluid Resuscitation Strategy","body":"**Aggressive but careful IV fluid therapy is cornerstone of DKA management.** [1][2][8]\n\n**Overall strategy:**\n• Correct dehydration: Most DKA patients are 5-8L depleted (sometimes >10L in severe DKA)\n• Target: Replace half deficit in first 8-12 hours, remainder over next 24 hours\n• Monitor: Reassess HR, BP, urine output, perfusion q1-2h\n• Adjust based on clinical response\n\n**Fluid choice (UPDATED 2024 ADA/EASD/JBDS Consensus):**\n• **Balanced crystalloid (LR, Plasmalyte) — PREFERRED FIRST-LINE when available:** 2024 consensus suggests balanced crystalloids over normal saline due to faster DKA resolution, less hyperchloremic acidosis (NAGMA), and shorter hospital LOS. [1][8]\n• **Normal saline (0.9%) — acceptable alternative:** Long-standing first-line that remains appropriate per institutional preference. Higher NAGMA risk with large-volume use.\n• Either is acceptable; institutional preference respected by 2024 ADA/EASD/JBDS guidelines.\n\n**Initial bolus:**\n• For volume depletion/shock: 500 mL-1 L IV bolus over 30-60 min (or 500-1000 mL/hr over 2-4 hours per 2024 consensus)\n• Reassess hemodynamics, urine output\n• Repeat bolus if needed to achieve HR <100-110, SBP >90-100\n• Caution in heart failure, ESRD, pregnancy — use POCUS to assess intravascular volume vs edema\n\n**Ongoing fluids after bolus:**\n• Depends on glucose level — see next decision point","citation":[1,2,8],"next":"dka-glucose-threshold","treatment":{"firstLine":{"drug":"Lactated Ringers or Plasmalyte (balanced crystalloid)","dose":"500 mL-1 L bolus, then 150-200 mL/hr","route":"IV","frequency":"Bolus over 30-60 min, then continuous","duration":"Replace half deficit in 8-12 hrs, rest over 24 hrs","notes":"PREFERRED per 2024 ADA/EASD/JBDS consensus — faster DKA resolution, less NAGMA, shorter LOS vs NS. Goal HR <100-110, SBP >90-100. Caution in HF/ESRD."},"alternative":{"drug":"Normal saline 0.9%","dose":"500 mL-1 L bolus, then 150-200 mL/hr","route":"IV","frequency":"Same as balanced crystalloid","duration":"Same protocol","notes":"Acceptable alternative. Higher hyperchloremic acidosis (NAGMA) risk with large-volume infusion. Institutional preference respected."},"monitoring":"HR, BP, UOP q1-2h. POCUS if HF/ESRD/pregnancy. Switch to \"drop and split\" when glucose <300."},"summary":"Balanced crystalloid (LR/Plasmalyte) preferred per 2024 consensus; NS acceptable. 500-1000 mL bolus, then 150-200 mL/hr. 5-8L depleted."}'::jsonb
WHERE id = 'dka-fluid-management' AND tree_id = 'dka';

-- Node: dka-stopping-criteria (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"DKA Resolution — Stopping Insulin Infusion","body":"**ALL of the following criteria must be met to stop IV insulin and transition to SC insulin:**\n\n**Stopping criteria (per 2025 ADA Standards of Care §16 + 2024 ADA/EASD/JBDS Consensus):** [1]\n1. **Anion gap <12** (essentially normalized, or approaching normal for chronic renal disease)\n2. **Venous pH >7.30** AND **serum bicarbonate ≥18 mEq/L** (or ≥15-20 if NAGMA present)\n3. **Plasma/capillary β-hydroxybutyrate (BOHB) <0.6 mmol/L** (2025 ADA resolution marker — preferred over AG alone in CKD/HD)\n4. **Basal insulin given** (glargine or equivalent) at least 2 hours prior to stopping drip — ensures 24-hour coverage\n5. **Glucose <250 mg/dL** (well-controlled)\n6. **Patient tolerate oral intake** (able to eat, holding down food/fluids) — critical for transition to meal-associated insulin\n\n**Do NOT stop insulin if:**\n• Any single criterion not met\n• Patient still vomiting — cannot absorb SC insulin\n• Acidosis worsening or not improving\n• K still critically low despite repletion\n\n**Transition protocol:**\n• Once all criteria met, stop IV insulin drip\n• Continue basal glargine (given on admission)\n• Start meal-time insulin: regular insulin or rapid-acting (aspart, lispro) with meals\n• Sliding scale insulin for glucose >150: 2-4 units per 50 mg/dL above 150\n• Target glucose 120-180 mg/dL during hospitalization\n\n**Timing:** Usually 12-24 hours from presentation if no complications. Longer if severe DKA or complications present.","citation":[1,2,5],"next":"dka-disposition-plan","summary":"Stop IV insulin when: AG <12, HCO3 >=18, glucose <250, tolerating PO, and basal given 2h+ prior."}'::jsonb
WHERE id = 'dka-stopping-criteria' AND tree_id = 'dka';

