UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Dual Antiplatelet Therapy (DAPT)","body":"**Loading (Day 1):**\n• [Aspirin](#/drug/aspirin/stroke) 325 mg + [Clopidogrel](#/drug/clopidogrel/stroke) 300 mg\n\n**Maintenance:**\n• Aspirin 81 mg + Clopidogrel 75 mg daily × 21 days\n• Then single antiplatelet (either agent)\n\n**Alternative (CYP2C19 poor metabolizer):**\n• [Ticagrelor](#/drug/ticagrelor/stroke) 180 mg load + Aspirin 325 mg, then Ticagrelor 90 mg BID + Aspirin 81 mg × 30 days (CHANCE-2 supports ticagrelor preference in CYP2C19 LOF carriers)\n\nPOINT trial: DAPT (dual antiplatelet therapy) reduced 90-day stroke from 6.5% to 5.0% (NNT 38). Duration beyond 21 days increases bleeding without additional benefit.\n\nAlso initiate statin (high-intensity) and complete stroke workup (telemetry, echo, vascular imaging).","citation":[3,9,10,12],"recommendation":"Start DAPT immediately. Limit duration to 21 days. Add high-intensity statin. Complete stroke etiology workup.","treatment":{"firstLine":{"drug":"Aspirin + Clopidogrel","dose":"Load: Aspirin 325 mg + Clopidogrel 300 mg; Maintenance: Aspirin 81 mg + Clopidogrel 75 mg","route":"PO","frequency":"Daily","duration":"21 days, then single antiplatelet","notes":"Do NOT extend DAPT beyond 21 days (increases bleeding without benefit)"},"alternative":{"drug":"Ticagrelor + Aspirin","dose":"Load: Ticagrelor 180 mg + Aspirin 325 mg; Maintenance: Ticagrelor 90 mg + Aspirin 81 mg","route":"PO","frequency":"Ticagrelor BID, Aspirin daily","duration":"30 days","notes":"For CYP2C19 poor metabolizers who cannot activate clopidogrel"},"monitoring":"Monitor for bleeding (GI, intracranial). Complete stroke etiology workup. Add high-intensity statin."},"confidence":"definitive"}'::jsonb
