-- Node: ugib-variceal-abx (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Antibiotic Prophylaxis","body":"**MANDATORY for all cirrhotic patients with GI bleeding:** [6][12][13][18][19]\n\n**First-line:**\n[Ceftriaxone](#/drug/ceftriaxone/ugib) 1g IV daily **up to 7 days** — AASLD 2024 allows discontinuation once hemostasis achieved and vasoactive drugs stopped\n\n**Alternative:**\nNorfloxacin 400 mg PO BID up to 7 days (avoid if high quinolone resistance)\n\n**Evidence:**\n• Reduces bacterial infections\n• Reduces rebleeding\n• May reduce mortality\n• Most infections occur within 5 days\n\n**Rationale:** Cirrhosis = gut translocation of bacteria. GI bleeding increases infection risk dramatically.\n\n📋 **Evolving Evidence (2025):** Prosty et al. Bayesian meta-analysis (JAMA Intern Med 2025) found 97.3% probability that shorter durations (2-3 days, or even none) are noninferior to longer courses for all-cause mortality, though longer courses still reduce documented bacterial infections. Accompanying Garcia-Tsao editorial: \"Antibiotic Prophylaxis in Variceal Hemorrhage — Time to Stop?\" Reasonable to discontinue once hemostasis stable and vasoactives off, especially in Child-Pugh A.\n\n**Note:** Child-Pugh A cirrhosis may have less benefit","citation":[6,12,13,18,19],"recommendation":"Ceftriaxone 1g IV daily up to 7 days for cirrhotic patients with GI bleeding. May discontinue once hemostasis achieved and vasoactives stopped (AASLD 2024).","treatment":{"firstLine":{"drug":"Ceftriaxone","dose":"1 g","route":"IV","frequency":"Daily","duration":"Up to 7 days","notes":"All cirrhotic patients with GI bleeding. AASLD 2024 allows discontinuation when hemostasis achieved and vasoactives stopped."},"alternative":{"drug":"Norfloxacin","dose":"400 mg","route":"PO","frequency":"BID","duration":"Up to 7 days","notes":"If ceftriaxone unavailable; avoid if quinolone resistance"},"monitoring":"Monitor for infection signs. Reassess need for continuation after hemostasis confirmed and vasoactives discontinued."},"confidence":"definitive"}'::jsonb
WHERE id = 'ugib-variceal-abx' AND tree_id = 'upper-gi-bleed';

-- Node: ugib-tips (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"TIPS Consultation","body":"**Transjugular Intrahepatic Portosystemic Shunt (TIPS):** [6][16][18]\n\n**AASLD 2024 Paradigm Shift:** At initial presentation with acute variceal hemorrhage, evaluate ALL patients for preemptive TIPS candidacy — not just rescue. Six-week mortality for AVH is 10-15%; high-risk patients benefit most. [18]\n\n**Preemptive (Early) TIPS — within 72h of admission:**\n• Child-Pugh C (score 10-13) with acute variceal bleeding\n• Child-Pugh B with active bleeding at index endoscopy\n• 1-year survival 86% vs 61% (medical therapy) in landmark Garcia-Pagan trial\n• Reduces rebleeding and mortality\n\n**Salvage/Rescue TIPS:**\n• Failed endoscopic therapy (2 attempts)\n• Rebleeding despite optimal medical + endoscopic therapy\n• Bridge to transplant\n\n**Contraindications:**\n• Right heart failure / pulmonary hypertension\n• Severe hepatic encephalopathy (uncontrolled)\n• Polycystic liver disease\n• MELD >18-20 (relative — survival benefit diminishes)\n\n**Complications:**\n• Hepatic encephalopathy (30-35%)\n• Shunt stenosis/occlusion\n• Liver failure / accelerated decompensation","citation":[6,16,18],"next":"ugib-disposition-decision","summary":"AASLD 2024: evaluate ALL AVH patients for preemptive TIPS at index presentation; Child-Pugh C or B-with-active-bleeding = preemptive TIPS <72h (86% vs 61% 1-yr survival)","skippable":true}'::jsonb
WHERE id = 'ugib-tips' AND tree_id = 'upper-gi-bleed';

